import React from "react";
import Layout from "../components/Layout";

const Dashboard = () => {
  // Sample data based on your modules & roles
  const modules = [
    {
      name: "Journal Management System",
      roles: [
        {
          role: "Admin / Journal Manager",
          description: "Manages users, journal settings, workflow, and tech.",
          responsibilities: [
            "Manage user accounts & permissions",
            "Configure journal settings and policies",
            "Oversee workflow and publication schedule",
          ],
        },
        {
          role: "Editor-in-Chief (EIC)",
          description: "Final academic decision maker for manuscripts",
          responsibilities: [
            "Make final manuscript decisions",
            "Assign Associate Editors",
            "Ensure ethical and quality standards",
          ],
        },
        {
          role: "Associate Editor",
          description: "Conducts initial screening, assigns reviewers",
          responsibilities: [
            "Desk review for scope and quality",
            "Select reviewers",
            "Recommend decisions to EIC",
          ],
        },
        {
          role: "Reviewer",
          description: "Peer reviews manuscripts",
          responsibilities: [
            "Evaluate manuscripts",
            "Provide structured feedback and recommendations",
          ],
        },
        {
          role: "Author",
          description: "Manuscript submitter and reviser",
          responsibilities: [
            "Submit manuscripts and metadata",
            "Respond to reviewer comments",
            "Ensure originality and ethics",
          ],
        },
      ],
    },
    {
      name: "eBook Publishing System",
      roles: [
        {
          role: "Author / Researcher",
          description: "Submit manuscripts for book publishing",
          responsibilities: [
            "Prepare and submit manuscripts and metadata",
            "Respond to review",
            "Approve final proof",
          ],
        },
        {
          role: "Book Editor",
          description: "Oversees publishing workflow",
          responsibilities: [
            "Initial manuscript screening",
            "Assign reviewers",
            "Decide acceptance or revision",
          ],
        },
        {
          role: "Peer Reviewer",
          description: "Reviews manuscript content",
          responsibilities: ["Provide critical review and feedback"],
        },
        {
          role: "Digital Content Manager",
          description: "Produces and uploads eBooks",
          responsibilities: [
            "Validate files",
            "Convert to eBook formats",
            "Upload and set metadata and permissions",
          ],
        },
        {
          role: "Finance & Operations Officer",
          description: "Manages payments for publication",
          responsibilities: ["Validate fees", "Issue invoices and clear financials"],
        },
        {
          role: "Reader / Public User",
          description: "Accesses and downloads published eBooks",
          responsibilities: ["Search, view, and download eBooks"],
        },
      ],
    },
    {
      name: "ORA Library Management System",
      roles: [
        {
          role: "Digital Librarian",
          description: "Manages digital collections and metadata",
          responsibilities: [
            "Upload/manage digital resources",
            "Ensure metadata accuracy",
            "Organize collections and user access",
          ],
        },
        {
          role: "Member / User / Student",
          description: "Library end user searching, borrowing, reading",
          responsibilities: [
            "Search catalog",
            "Borrow/return items",
            "Request/renew/hold items",
          ],
        },
        {
          role: "Admin",
          description: "System configuration and user management",
          responsibilities: ["Manage users and permissions", "Configure system", "Backup and security"],
        },
        {
          role: "Content Uploader (Optional)",
          description: "Uploads digital content for approval",
          responsibilities: ["Upload ebooks, journals, papers", "Enter metadata"],
        },
        {
          role: "External Publisher (Optional)",
          description: "Provides licensed/subscribed content",
          responsibilities: ["Supply licensed content", "Maintain metadata and compliance"],
        },
        {
          role: "Physical Librarian",
          description: "Manages physical library services",
          responsibilities: ["Lending and returns", "Holds and renewals", "Fine collection and patron assistance"],
        },
        {
          role: "Library Manager",
          description: "Oversees physical library operations",
          responsibilities: ["Staff supervision", "Set policies", "Approve acquisitions and reports"],
        },
        {
          role: "Acquisition Officer",
          description: "Procures physical books and materials",
          responsibilities: ["Order and inspect materials", "Coordinate with Cataloger"],
        },
        {
          role: "Cataloger",
          description: "Classifies and catalogs physical materials",
          responsibilities: ["Assign call numbers, barcodes", "Update catalog records"],
        },
        {
          role: "Inventory Manager",
          description: "Maintains inventory and audits",
          responsibilities: ["Conduct stocktaking and audits", "Manage tagging and inventory accuracy"],
        },
      ],
    },
    {
      name: "Oromo Wikipedia Platform",
      roles: [
        {
          role: "Registered Editor",
          description: "Creates/edits articles and media",
          responsibilities: ["Edit articles", "Upload free-license media", "Participate in content discussions"],
        },
        {
          role: "Administrator (Sysop)",
          description: "Manages content and user behavior",
          responsibilities: ["Delete/restore pages", "Block disruptive users", "Protect pages"],
        },
        {
          role: "Bureaucrat & Global Steward",
          description: "Manages user roles and global actions",
          responsibilities: ["Promote/demote admins", "Rename/lock users globally"],
        },
        {
          role: "Oversighter / CheckUser",
          description: "Controls abuse and privacy-sensitive information",
          responsibilities: ["Suppress private revisions", "View IP/user data in abuse cases"],
        },
      ],
    },
    {
      name: "ORA Repository Management System",
      roles: [
        {
          role: "Researcher / Author",
          description: "Deposits scholarly works with bibliographic metadata",
          responsibilities: [
            "Upload documents with bibliographic data",
            "Specify access level",
            "Ensure copyright/citation compliance",
          ],
        },
        {
          role: "Repository Curator",
          description: "Validates metadata and manages access",
          responsibilities: ["Review/enrich metadata", "Apply access controls", "Organize and tag resources"],
        },
        {
          role: "Content Reviewer",
          description: "Verifies content quality and bibliographic integrity",
          responsibilities: ["Check academic quality", "Plagiarism check", "Citation accuracy"],
        },
        {
          role: "Repository Administrator",
          description: "Oversees repository operation and access",
          responsibilities: ["Final approvals", "Manage access, copyright, citation compliance", "Generate reports"],
        },
      ],
    },
    {
      name: "Researchers' Network Platform",
      roles: [
        {
          role: "Researcher / Member",
          description: "Connects, collaborates, and shares research",
          responsibilities: ["Create profiles", "Network and join groups", "Share updates"],
        },
        {
          role: "Group Moderator",
          description: "Manages research groups and enforces community guidelines",
          responsibilities: ["Approve memberships", "Moderate discussions and conflicts"],
        },
        {
          role: "Platform Administrator",
          description: "Manages platform settings and user roles",
          responsibilities: ["User management", "Security and maintenance", "Content curation"],
        },
        {
          role: "Event/Content Manager",
          description: "Publishes calls, events, and updates",
          responsibilities: ["Manage announcements", "Notify users", "Promote activities"],
        },
      ],
    },
  ];

  return (
    <Layout>
      <section className="content-header">
        <div className="container-fluid">
          <h1>ORA System Dashboard</h1>
          <p>Total Modules: {modules.length}</p>
        </div>
      </section>

      <section className="content">
        <div className="container-fluid">
          {modules.map((module, idx) => (
            <div className="card mb-4" key={idx}>
              <div className="card-header bg-success">
                <h3 className="card-title">{module.name}</h3>
              </div>
              <div className="card-body">
                <table className="table table-bordered table-hover">
                  <thead>
                    <tr className="table-primary">
                      <th>Role Name</th>
                      <th>Description</th>
                      <th>Key Responsibilities</th>
                    </tr>
                  </thead>
                  <tbody>
                    {module.roles.map((role, rIdx) => (
                      <tr key={rIdx}>
                        <td>{role.role}</td>
                        <td>{role.description}</td>
                        <td>
                          <ul className="mb-0">
                            {role.responsibilities.map((resp, respIdx) => (
                              <li key={respIdx}>{resp}</li>
                            ))}
                          </ul>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ))}
        </div>
      </section>
    </Layout>
  );
};

export default Dashboard;
